import React from 'react';
import { useLocation } from 'react-router-dom';
import HeaderShop from '../../components/E-Commerce/AllProducts/HeaderShop';
import MedicineCartAddress from '../../components/E-Commerce/MedicineCartAddress';
import Preloader from '../../helper/Preloader';
import FooterOne from '../../components/FooterOne';

const MedicineCartAddressPage = () => {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);
  const searchParam = queryParams.get('search') || '';

  return (
    <>
      <Preloader />
      <HeaderShop initialSearchQuery={searchParam} />
      <MedicineCartAddress />
      <FooterOne />
    </>
  );
};

export default MedicineCartAddressPage;
